import{_ as a,o as s,c as d,a2 as e}from"./chunks/framework.DDEX3mHW.js";const g=JSON.parse('{"title":"订阅","description":"","frontmatter":{},"headers":[],"relativePath":"guide/subscription.md","filePath":"guide/subscription.md","lastUpdated":1792228607000}'),o={name:"guide/subscription.md"};function i(l,t,r,n,h,c){return s(),d("div",null,[...t[0]||(t[0]=[e(`<h1 id="订阅" tabindex="-1">订阅 <a class="header-anchor" href="#订阅" aria-label="Permalink to &quot;订阅&quot;">​</a></h1><p><strong>订阅</strong> 页管理所有订阅链接。思路和 Sub-Store 一样：<strong>来源 → 处理 → 输出</strong>。每个订阅选一批落地，按需过滤、改名，客户端拿到的格式按 UA 自动识别（也可以复制指定格式的链接）。</p><p>升级前的订阅链接会变成这里的“我的订阅”，链接不变；原来的订阅设置和共享用户也会自动迁移过来。</p><h2 id="订阅与凭据" tabindex="-1">订阅与凭据 <a class="header-anchor" href="#订阅与凭据" aria-label="Permalink to &quot;订阅与凭据&quot;">​</a></h2><p>所有订阅在同一个列表里，靠名称区分（例如“我的手机”“小明”）。</p><ul><li>新建的订阅都有自己的 UUID / 密码，和你的凭据同时写进节点配置，互不影响</li><li>可以设到期日期（到期当天 23:59 后断开）和流量上限，留空就是不限；停用、到期或流量用完后，面板会把它的凭据从节点上删掉</li></ul><p>编辑时“处理”和“链式代理”默认收起（已设置的会展开），标题旁显示已开启的项目。</p><h2 id="导入到客户端" tabindex="-1">导入到客户端 <a class="header-anchor" href="#导入到客户端" aria-label="Permalink to &quot;导入到客户端&quot;">​</a></h2><p>点订阅打开详情，按客户端选择：<strong>点客户端直接唤起 App 导入</strong>，右侧按钮复制该格式的链接。也可以复制上面的通用链接，客户端按 UA 自动拿到对应格式。</p><table tabindex="0"><thead><tr><th>客户端</th><th>格式</th><th>一键导入</th><th>链式代理</th></tr></thead><tbody><tr><td>Clash（Clash Verge、Mihomo Party、FlClash 等）</td><td>Clash / Mihomo 配置</td><td><code>clash://</code></td><td>✓</td></tr><tr><td>sing-box（SFA / SFI / SFM）</td><td>sing-box 配置</td><td><code>sing-box://</code></td><td>✓</td></tr><tr><td>Shadowrocket</td><td>Clash 节点列表</td><td><code>shadowrocket://</code></td><td>✓（每个中转各生成一个“落地（经 中转）”节点）</td></tr><tr><td>Loon</td><td>Loon 节点</td><td><code>loon://</code></td><td>✗</td></tr><tr><td>Quantumult X</td><td>QX 节点</td><td><code>quantumult-x://</code></td><td>✗</td></tr><tr><td>Surge</td><td>Surge 配置</td><td><code>surge://</code></td><td>✓</td></tr><tr><td>Stash</td><td>Clash 配置</td><td><code>stash://</code></td><td>✓</td></tr><tr><td>通用</td><td>Base64 分享链接（v2rayN、NekoBox 等）</td><td>仅复制</td><td>✗</td></tr></tbody></table><ul><li>客户端不支持的协议会自动略过，例如 Loon 没有 TUIC，Quantumult X 没有 Hysteria2 / TUIC，Surge 没有 VLESS</li><li>Loon 和 Quantumult X 的节点格式没有前置代理参数，订阅里的落地节点是直连</li><li>指定格式的链接：在订阅链接后加 <code>?format=clash</code>（或 <code>singbox</code>、<code>shadowrocket</code>、<code>loon</code>、<code>qx</code>、<code>surge</code>、<code>stash</code>、<code>base64</code>）</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><ul><li><strong>全部落地</strong>：包括以后新增的落地，不用再回来勾选</li><li><strong>指定落地</strong>：只勾选需要的，分“自建”“导入”和“订阅源”三组。订阅源按整个源勾选，以后更新进来的节点会自动跟上；只要其中一部分可以用下面的过滤</li></ul><p>落地的中转线路会跟着它一起出现在订阅里。</p><h2 id="订阅源" tabindex="-1">订阅源 <a class="header-anchor" href="#订阅源" aria-label="Permalink to &quot;订阅源&quot;">​</a></h2><p>在 <strong>落地 → 订阅源</strong> 添加机场或别人的订阅链接，相当于 Sub-Store 的远程订阅。也可以在 <strong>落地 → 导入</strong> 里粘贴订阅地址，打开 <strong>定时同步</strong>（默认打开）就会存成订阅源；关掉则只导入一次：</p><ul><li>添加后立即拉取一次，节点出现在 <strong>落地</strong> 页“订阅源 · 名称”分组里，可以和其他导入节点一样检测、接中转、放进订阅</li><li><strong>自动更新</strong>：手动 / 6 小时 / 12 小时 / 每天。也可以点卡片右边的按钮立即更新</li><li>更新时按 <strong>名称</strong> 对上已有节点（名称变了再按地址对）：地址变了就跟着改，挂在上面的中转也会改到新地址；订阅里没有了就删除，但挂着中转的会保留，免得中转断掉</li><li>拉取失败或返回空内容时保留现有节点，卡片上显示错误</li><li>机场返回的流量和到期信息（<code>Subscription-Userinfo</code>）会显示在卡片上</li><li><strong>新节点设为仅中转</strong>：新加进来的节点只用来接中转，不直接进订阅</li><li>删除订阅源时可以选连同节点一起删除，或只删订阅源、节点留下变成普通的导入节点</li></ul><p>典型用法：订阅选“指定落地”，勾上自己的落地和机场订阅源，再用“处理”过滤地区、加国旗、排序，一个链接全搞定。</p><h2 id="处理" tabindex="-1">处理 <a class="header-anchor" href="#处理" aria-label="Permalink to &quot;处理&quot;">​</a></h2><p>按固定顺序执行：<strong>过滤 → 改名 → 国旗 → 前缀 → 去重 → 排序</strong>，最后输出时可以按地区分组。</p><table tabindex="0"><thead><tr><th>步骤</th><th>说明</th></tr></thead><tbody><tr><td>线路</td><td>全部 / 只要中转 / 只要直连</td></tr><tr><td>地区</td><td>只保留选中的地区；“其他”是名称里认不出地区的节点</td></tr><tr><td>协议</td><td>只保留选中的协议</td></tr><tr><td>名称包含 / 排除</td><td>多个关键词用 <code>|</code> 分隔（不区分大小写），或用 <code>/正则/</code></td></tr><tr><td>改名规则</td><td>每行一条 <code>要替换的 =&gt; 替换成</code>，右边留空就是删除，<code>/.../</code> 是正则</td></tr><tr><td>自动加国旗</td><td>按名称识别地区，在前面加国旗；已经有国旗的不重复加</td></tr><tr><td>名称前缀</td><td>给所有节点加同一个前缀</td></tr><tr><td>去重</td><td>地址、端口、协议都相同的只保留第一个</td></tr><tr><td>排序</td><td>面板顺序，或按名称（<code>02</code> 排在 <code>10</code> 前面）</td></tr><tr><td>按地区分组</td><td>Clash / sing-box / Surge 里每个地区一个自动测速组，列在“节点选择”最前面</td></tr></tbody></table><p>例如导入的节点叫 <code>花云|香港🇭🇰|1.0x|01</code>，改名规则：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>花云| =&gt;</span></span>
<span class="line"><span>/\\|[0-9.]+x/ =&gt;</span></span>
<span class="line"><span>| =&gt; -</span></span></code></pre></div><p>会变成 <code>香港🇭🇰-01</code>。编辑时点 <strong>看看结果</strong> 可以先预览，会显示每个节点改名前后的名字和过滤掉了几个。</p><h2 id="链式代理" tabindex="-1">链式代理 <a class="header-anchor" href="#链式代理" aria-label="Permalink to &quot;链式代理&quot;">​</a></h2><p>让客户端先连 <strong>中转节点</strong>，再经它连 <strong>落地节点</strong>，网站看到的是落地节点的 IP。适合“国内 → 香港中转 → 美国落地”这类线路，或者给机场节点套一层自己的落地。</p><p>在订阅的 <strong>链式代理</strong> 里填两个名称表达式（写法同“名称包含”）：</p><ul><li><strong>落地节点</strong>：匹配到的节点挂上中转组，即 Clash / Mihomo 的 <code>dialer-proxy</code>、sing-box 的 <code>detour</code>、Surge 的 <code>underlying-proxy</code></li><li><strong>中转节点</strong>：匹配到的节点放进“中转节点”组</li></ul><p>生成的订阅里多两个分组：</p><table tabindex="0"><thead><tr><th>分组</th><th>说明</th></tr></thead><tbody><tr><td>落地节点</td><td>选出口，排在“节点选择”的第一个</td></tr><tr><td>中转节点</td><td>选中转，所有落地节点都经这里选中的节点连接</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">proxies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;美国 落地 01&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vless</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # ...</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    dialer-proxy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;中转节点&quot;</span></span></code></pre></div><ul><li>两项都填且都匹配到节点才生效；同时匹配两项的节点算落地</li><li>匹配的是改名后的名字，也认原名；预览里会标出“落地”“中转”</li><li>落地节点仍可在“节点选择”和地区分组里直接选，选中后同样经中转连接；中转节点也可以单独使用</li><li>通用分享链接（Base64）无法表达链式，落地节点在里面是直连</li><li>延迟叠加，速度取决于最慢的一段；落地是 Hysteria2 / TUIC 等 UDP 协议时，中转节点要能转发 UDP</li></ul><blockquote><p>这是客户端侧的链式。想让服务器自己把流量转到另一个节点出去（客户端无感），用入站的 <a href="./nodes#分流">分流</a>。</p></blockquote><h2 id="独立凭据" tabindex="-1">独立凭据 <a class="header-anchor" href="#独立凭据" aria-label="Permalink to &quot;独立凭据&quot;">​</a></h2><ul><li>每个订阅有自己的 UUID / 密码，和你的凭据同时写进节点配置，互不影响</li><li><strong>停用</strong>、<strong>删除</strong> 或 <strong>到期</strong> 后，面板会把它的凭据从节点上删掉，已导入的配置也连不上了</li><li><strong>重置链接和凭据</strong>：旧链接和对方已导入的配置立即失效，适合链接泄露时使用</li><li>支持单独凭据的协议：VLESS、VMess、Trojan、Hysteria2、TUIC、AnyTLS、NaïveProxy。Shadowsocks、Snell 和导入的节点只能共用原来的密码：停用后订阅失效，但对方已经导入的配置仍能连接（界面上会标出“共用凭据”）</li><li>3 天内到期会推送 <a href="./notify">通知</a></li></ul><h3 id="流量上限" tabindex="-1">流量上限 <a class="header-anchor" href="#流量上限" aria-label="Permalink to &quot;流量上限&quot;">​</a></h3><ul><li>每个订阅单独统计流量（上传 + 下载），可以设 <strong>流量上限</strong>，用完自动断开，和到期一样</li><li><strong>每月重置</strong>：选每月几号，到那天 0 点自动清零；也可以在订阅详情里点 <strong>重置流量</strong> 手动清零，超限断开的会立即恢复</li><li>用到 90% 和用完时会推送 <a href="./notify">通知</a>，概览页的“需要处理”里也会列出</li><li>客户端里能看到已用流量、总量和到期时间（<code>Subscription-Userinfo</code>）</li><li>统计在落地节点上进行：每个订阅走自己的出站，节点用 nftables 计数，Xray 和 sing-box 都支持。需要节点上有 nftables，并且节点 agent 要和面板一起更新到最新版（旧 agent 能正常转发，只是不计数）</li><li>只统计支持单独凭据的协议。共用凭据的落地（Shadowsocks、Snell、导入的节点）分不清是谁在用，不计入</li></ul><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><ul><li>点订阅可以导入到客户端、复制各种格式的链接、编辑、重置链接或删除</li><li>所有订阅都包含在 <strong>网站配置 → 数据备份与恢复</strong> 的“内核与入站”里</li></ul>`,39)])])}const u=a(o,[["render",i]]);export{g as __pageData,u as default};
